import type { AdvanceGalleryCard, GalleryLens } from '../core/galleryTypes';

export type PeakGalleryCard = AdvanceGalleryCard & {
  primaryLens: GalleryLens;
  lenses: GalleryLens[];
};

function previewSvg(title: string, lens: GalleryLens, colors: [string, string, string], variant: number): string {
  const escape = (value: string) => value.replace(/[<>&'"]/g, (ch) => ({ '<':'&lt;', '>':'&gt;', '&':'&amp;', "'":'&apos;', '"':'&quot;' }[ch] ?? ch));
  const [a,b,c] = colors;
  const art = [
    '<rect x="70" y="100" width="500" height="500" rx="34" fill="rgba(255,255,255,.07)" stroke="rgba(255,255,255,.18)"/><circle cx="860" cy="340" r="190" fill="'+c+'" opacity=".62"/><rect x="670" y="150" width="360" height="370" rx="30" fill="'+b+'" opacity=".28"/>',
    '<rect x="85" y="100" width="440" height="545" rx="24" fill="'+b+'" opacity=".44"/><rect x="560" y="125" width="540" height="500" rx="28" fill="rgba(255,255,255,.08)"/><circle cx="930" cy="250" r="142" fill="'+c+'" opacity=".55"/>',
    '<text x="82" y="375" font-size="132" font-family="Arial" font-weight="800" fill="white">TYPE</text><rect x="82" y="426" width="710" height="25" fill="'+c+'"/><circle cx="930" cy="350" r="150" fill="'+b+'" opacity=".68"/>',
    '<polyline points="90,560 260,430 410,500 565,295 735,350 920,170 1100,240" fill="none" stroke="'+c+'" stroke-width="9"/><g fill="'+b+'" opacity=".9"><rect x="120" y="360" width="84" height="200"/><rect x="275" y="290" width="84" height="270"/><rect x="430" y="390" width="84" height="170"/><rect x="585" y="230" width="84" height="330"/></g>',
    '<circle cx="600" cy="355" r="215" fill="none" stroke="'+c+'" stroke-width="34" opacity=".82"/><circle cx="600" cy="355" r="118" fill="'+b+'" opacity=".68"/><circle cx="600" cy="355" r="300" fill="none" stroke="rgba(255,255,255,.13)" stroke-width="2"/>',
    '<circle cx="310" cy="210" r="260" fill="'+c+'" opacity=".35"/><circle cx="880" cy="500" r="300" fill="'+b+'" opacity=".3"/><path d="M0 520 C240 380 400 700 620 500 S980 260 1200 480" fill="none" stroke="rgba(255,255,255,.28)" stroke-width="2"/>',
    '<rect x="80" y="90" width="1040" height="575" rx="34" fill="rgba(255,255,255,.055)" stroke="'+c+'" stroke-opacity=".5"/><circle cx="875" cy="290" r="170" fill="'+b+'" opacity=".38"/><rect x="130" y="180" width="520" height="72" rx="18" fill="'+c+'" opacity=".72"/><rect x="130" y="300" width="390" height="22" rx="11" fill="white" opacity=".52"/><rect x="130" y="344" width="470" height="22" rx="11" fill="white" opacity=".24"/>'
  ][variant % 7];
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="'+a+'"/><stop offset=".58" stop-color="'+b+'"/><stop offset="1" stop-color="'+a+'"/></linearGradient></defs><rect width="1200" height="760" fill="url(#g)"/>'+art+'<rect x="42" y="40" width="160" height="36" rx="18" fill="rgba(0,0,0,.36)" stroke="rgba(255,255,255,.22)"/><text x="122" y="63" text-anchor="middle" font-size="14" font-family="monospace" fill="white" font-weight="700">'+escape(lens.toUpperCase())+'</text><text x="58" y="704" font-size="34" font-family="Arial" fill="white" font-weight="700">'+escape(title)+'</text><text x="58" y="736" font-size="15" font-family="monospace" fill="rgba(255,255,255,.68)">APEXIFY.JS / PEAK GALLERY</text></svg>';
  return 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg);
}

function jsFromTs(ts: string): string {
  return ts.replace(/^import \{ ApexPainter \} from 'apexify\.js';\n\n/, '');
}

function source(body: string): string {
  return "import { ApexPainter } from 'apexify.js';\n\nconst painter = new ApexPainter();\n\nasync function main() {\n" + body.trim() + "\n}\n\nreturn await main();\n";
}

